  function colorLanguage(s){if(s.color==='Custom Palette'&&s.customHex)return`Use the exact custom palette ${s.customHex}, assigning dominant, support, and accent roles with intentional contrast.`;const map={'Monochrome':'Build tonal depth from one hue through value, opacity, and texture shifts.','Black + White':'Use decisive black-and-white contrast with clean separation and no muddy grays.','Pastel':'Use airy pastels with one firmer anchor color for small-format clarity.','Neon':'Let neon accents ignite against dark anchors without allowing every surface to glow.','Warm Jewel Tone':'Use warm ruby, amber, garnet, and burnished-gold behavior with rich controlled saturation.','High Contrast':'Separate the focal subject from supporting forms with decisive light-dark and complementary contrast.','Vintage Fade':'Use sun-faded inks, softened contrast, and slightly aged color registration.','Metallic Accent':'Keep the base palette grounded and reserve metallic highlights for focal hierarchy.'};return map[s.color]||`Use a ${s.color.toLowerCase()} palette with a clear dominant color, supporting hues, and a restrained accent; control saturation and contrast around the focal point.`}
  function applyMaterialZones(s){const secondary=s.secondaryMaterial&&s.secondaryMaterial!=='None'?s.secondaryMaterial:null;let primaryZone='focal surfaces and key dimensional accents',secondaryZone='supporting details';if(/Typography/.test(s.composition)||s.exactText){primaryZone='headline typography and its dimensional edge';secondaryZone=isPeopleBased(s)?'jewelry, garment trim, and small accents':'supporting icons and border details'}else if(automotiveSubjects.includes(s.subject)){primaryZone='vehicle highlights, trim, and selected wheel accents';secondaryZone='speed marks and background graphics'}else if(fashionSubjects.includes(s.subject)||beautySubjects.includes(s.subject)){primaryZone='hero garment or accessory accents';secondaryZone='jewelry, typography, and decorative details'}else if(foodSubjects.includes(s.subject)){primaryZone='packaging accents and dimensional highlights';secondaryZone='garnish icons and label framing'}return`Render ${s.material.toLowerCase()} as a printable visual illusion specifically on the ${primaryZone}${secondary?`, and zone ${secondary.toLowerCase()} onto the ${secondaryZone}`:''}. Use highlights, texture, and depth cues only in those zones; do not coat the entire design and do not imply physical materials.`}
