  function shakeModal(){const locks=new Set(state.shakeLocks);const items=[['subject','Keep Subject'],['character','Keep Character'],['style','Keep Style'],['era','Keep Era'],['color','Keep Colors'],['material','Keep Material'],['composition','Keep Composition'],['typography','Keep Typography'],['mood','Keep Mood'],['format','Keep Sticker Format']];openModal('SHAKE THE BOX','Controlled creative randomness with weighted relationships and persistent smart locks.',`<div class="form-field"><label>SURPRISE LEVEL</label><select id="surpriseLevel"><option ${state.surpriseLevel==='SAFE'?'selected':''}>SAFE</option><option ${state.surpriseLevel==='FRESH'?'selected':''}>FRESH</option><option ${state.surpriseLevel==='WILD'?'selected':''}>WILD</option></select></div><div class="option-grid">${items.map(([k,n])=>`<button class="option lock ${locks.has(k)?'selected':''}" data-lock="${k}">${n}</button>`).join('')}</div><p>${esc($('#promptInput').value)}</p><div class="modal-actions"><button id="shakeAgain">SHAKE AGAIN</button><button id="shakeAll" class="lime">ϟ SHAKE EVERYTHING & BUILD</button></div>`);$$('.lock').forEach(x=>x.onclick=()=>{x.classList.toggle('selected');x.classList.contains('selected')?locks.add(x.dataset.lock):locks.delete(x.dataset.lock);state.shakeLocks=[...locks]});const run=close=>{state.surpriseLevel=$('#surpriseLevel').value;shake(locks,state.surpriseLevel);if(close){closeModal();toast(`${state.surpriseLevel} shake built; smart locks preserved`)}else shakeModal()};$('#shakeAgain').onclick=()=>run(false);$('#shakeAll').onclick=()=>run(true)}
